import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { Button, Z_INDEX_ONBOARDING_TOUR } from 'platform-bible-react';
import { readDirection } from 'platform-bible-react/experimental';
import { formatReplacementString, LocalizeKey } from 'platform-bible-utils';

/**
 * Localize keys for the tour's own chrome — the navigation buttons and the step counter. The
 * consumer resolves these (together with its own per-step title/description keys) and passes the
 * result down as {@link TourProps.localizedStrings}, so the key list has a single typed source
 * rather than being restated by hand at the call site.
 *
 * Back and Next reuse the first-run wizard's labels rather than shipping two more "Back"/"Next"
 * strings for translators; `%general_countOfTotal%` supplies the counter.
 */
export const TOUR_STRING_KEYS = Object.freeze([
  '%firstRun_button_back%',
  '%firstRun_button_next%',
  '%onboardingTour_button_done%',
  '%onboardingTour_button_skip%',
  '%general_countOfTotal%',
] as const);

/** Same keys as {@link TOUR_STRING_KEYS}, widened for `useLocalizedStrings`. */
export const TOUR_LOCALIZE_KEYS: LocalizeKey[] = [...TOUR_STRING_KEYS];

/**
 * Localized strings consumed by {@link Tour}. Every key is optional; each read falls back to English
 * so the component still renders readable chrome in a story or test that supplies nothing.
 */
export type TourLocalizedStrings = {
  [key in (typeof TOUR_STRING_KEYS)[number]]?: string;
};

/** One stop in the guided tour. */
export interface TourStep {
  /**
   * CSS selector for the element to spotlight. A step whose target is absent — or present but
   * zero-size, e.g. an empty wrapper whose conditional child is not rendered — is skipped.
   */
  target: string;
  /** Heading shown in the step card. */
  title: string;
  /** Body text shown in the step card. */
  description: string;
  /**
   * Logical side of the target on which the card appears. `start`/`end` resolve to physical
   * left/right via `readDirection()`, so callers never branch on RTL. In LTR (default):
   * `start`=left, `end`=right; in RTL these are swapped.
   *
   * @default 'bottom'
   */
  side?: 'top' | 'bottom' | 'start' | 'end';
  /**
   * Padding (px) added outside the target's bounding rect on all four sides to create the spotlight
   * cutout. Use a small positive value (e.g. 1) for column panels where the rc-dock divider
   * visually extends ~7 px into the panel — `spotlightPadding: 1` places the spotlight edge at the
   * divider's visual center so neither adjacent panel bleeds into the lit area.
   *
   * @default 6
   */
  spotlightPadding?: number;
}

/** Props accepted by the {@link Tour} component. */
export interface TourProps {
  /**
   * Ordered list of steps. Steps whose target selector is not found are skipped.
   *
   * **Snapshotted at open:** the list is filtered once when `open` flips to `true`. Steps added
   * after that point — or steps whose targets mount after the tour opens — are not picked up until
   * the tour re-opens. Pass steps only after the targets you intend to spotlight are already in the
   * DOM.
   */
  steps: TourStep[];
  /** Whether the tour overlay is visible. */
  open: boolean;
  /** Called when the user finishes the last step (Done). */
  onDone: () => void;
  /** Called when the user dismisses the tour (Skip button or Escape). */
  onSkip: () => void;
  /** Resolved values for {@link TOUR_STRING_KEYS}. Absent keys fall back to English. */
  localizedStrings?: TourLocalizedStrings;
}

interface TargetRect {
  top: number;
  left: number;
  width: number;
  height: number;
}

const CARD_WIDTH_PX = 288;
const CARD_APPROX_HEIGHT_PX = 176;
const CARD_GAP_PX = 12;
const SPOTLIGHT_PADDING_PX = 6;
/**
 * Opacity of the dimming scrim outside the spotlight cutout. Heavier than the dialog and drawer
 * overlays on purpose: those sit under an opaque panel that supplies its own contrast, whereas the
 * tour's un-cut area has to read as clearly de-emphasized against the lit cutout beside it.
 */
const SCRIM_OPACITY = 0.55;

/**
 * Returns the bounding rect of the first element matching `selector`, or `undefined` if absent. An
 * `undefined` return causes the step to be skipped — see {@link Tour} for skip semantics.
 */
function measureTarget(selector: string): TargetRect | undefined {
  const el = document.querySelector(selector);
  if (!el) return undefined;
  const r = el.getBoundingClientRect();
  // Skip elements that are in the DOM but have no visual area (e.g. an empty wrapper div
  // whose conditional children are not rendered). A zero-size rect produces a degenerate
  // 2×padding spotlight over an invisible point, which is misleading to the user.
  if (r.width <= 0 || r.height <= 0) return undefined;
  return { top: r.top, left: r.left, width: r.width, height: r.height };
}

/**
 * Resolves a logical side to a physical one for the current layout direction.
 *
 * `readDirection()` reports the UI's global layout direction — the same signal the rest of the app
 * mirrors from, so the tour inherits whatever direction the surrounding layout is laid out in
 * rather than deciding one of its own. It is not on its own evidence that any particular
 * container's children are mirrored; see the RTL story in `tour.stories.tsx` for the visual check.
 */
function resolvePhysicalSide(
  side: 'top' | 'bottom' | 'start' | 'end',
): 'top' | 'bottom' | 'left' | 'right' {
  if (side === 'top' || side === 'bottom') return side;
  const isRtl = readDirection() === 'rtl';
  if (side === 'start') return isRtl ? 'right' : 'left';
  return isRtl ? 'left' : 'right'; // 'end'
}

const VIEWPORT_MARGIN_PX = 8;

/**
 * Computes card position relative to the spotlight target. When the card cannot fit on the
 * requested side, it flips to the opposite side if that one fits — clamping alone would slide the
 * card over its own target. The result is always clamped into the viewport as a last resort (e.g.
 * when neither side fits).
 */
function computeCardPosition(
  rect: TargetRect,
  requestedSide: 'top' | 'bottom' | 'left' | 'right',
  cardHeightPx: number,
): { top: number; left: number } {
  const clampLeft = (l: number) =>
    Math.max(
      VIEWPORT_MARGIN_PX,
      Math.min(l, window.innerWidth - CARD_WIDTH_PX - VIEWPORT_MARGIN_PX),
    );
  const clampTop = (t: number) =>
    Math.max(
      VIEWPORT_MARGIN_PX,
      Math.min(t, window.innerHeight - cardHeightPx - VIEWPORT_MARGIN_PX),
    );
  // Above or below the target the card runs along the inline axis, so it hangs from the target's
  // inline-start edge: its left edge in LTR, its right edge in RTL. Aligning to `rect.left` in both
  // directions would push the card away from the reading direction, and into the opposite clamp for
  // a target sitting near the inline-start edge of an RTL viewport.
  const inlineStartLeft =
    readDirection() === 'rtl' ? rect.left + rect.width - CARD_WIDTH_PX : rect.left;
  const fits = {
    top: rect.top - CARD_GAP_PX - cardHeightPx >= VIEWPORT_MARGIN_PX,
    bottom:
      rect.top + rect.height + CARD_GAP_PX + cardHeightPx <=
      window.innerHeight - VIEWPORT_MARGIN_PX,
    left: rect.left - CARD_WIDTH_PX - CARD_GAP_PX >= VIEWPORT_MARGIN_PX,
    right:
      rect.left + rect.width + CARD_GAP_PX + CARD_WIDTH_PX <=
      window.innerWidth - VIEWPORT_MARGIN_PX,
  };
  const opposite = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' } as const;
  const physicalSide =
    !fits[requestedSide] && fits[opposite[requestedSide]] ? opposite[requestedSide] : requestedSide;
  switch (physicalSide) {
    case 'top':
      return {
        top: clampTop(rect.top - CARD_GAP_PX - cardHeightPx),
        left: clampLeft(inlineStartLeft),
      };
    case 'left':
      return { top: clampTop(rect.top), left: clampLeft(rect.left - CARD_WIDTH_PX - CARD_GAP_PX) };
    case 'right':
      return { top: clampTop(rect.top), left: clampLeft(rect.left + rect.width + CARD_GAP_PX) };
    default: // bottom
      return {
        top: clampTop(rect.top + rect.height + CARD_GAP_PX),
        left: clampLeft(inlineStartLeft),
      };
  }
}

/**
 * Spotlight-overlay guided tour. Renders a full-viewport SVG mask (white fill + black cutout = a
 * transparent "hole" over the target) that dims the page except around the current target element,
 * and positions a step card beside it.
 *
 * Navigated with Back / Next / Skip / Done; Escape dismisses (calls `onSkip`). Steps whose target
 * selector is not found in the DOM — or resolves to a zero-size element — when the tour opens are
 * skipped, so an absent target degrades gracefully instead of killing the overlay. A step whose
 * target disappears _after_ the tour opens is dropped the same way when it becomes current. If that
 * leaves nothing to spotlight, `onSkip` is called so the caller is never left with an open tour
 * that renders nothing. Returns `null` when `open` is false or the current step is not yet
 * measured.
 */
export function Tour({ steps, open, onDone, onSkip, localizedStrings }: TourProps) {
  const backLabel = localizedStrings?.['%firstRun_button_back%'] ?? 'Back';
  const nextLabel = localizedStrings?.['%firstRun_button_next%'] ?? 'Next';
  const doneLabel = localizedStrings?.['%onboardingTour_button_done%'] ?? 'Done';
  const skipLabel = localizedStrings?.['%onboardingTour_button_skip%'] ?? 'Skip tour';
  const counterTemplate = localizedStrings?.['%general_countOfTotal%'] ?? '{count} of {total}';

  // Resolve which steps actually have a target in the DOM, computed when the tour opens.
  // Steps whose targets mount after open() fires are not picked up until the tour re-opens.
  const [visibleSteps, setVisibleSteps] = useState<TourStep[]>([]);
  const [stepIndex, setStepIndex] = useState(0);
  // The measured rect is stored together with the step it was measured for, so `targetRect` below
  // can be derived by identity. Without that pairing a rect measured for one step would still be
  // on screen after advancing to the next, spotlighting the previous step's element under the new
  // step's copy whenever the new target can no longer be measured.
  const [measuredTarget, setMeasuredTarget] = useState<
    { step: TourStep; rect: TargetRect } | undefined
  >(undefined);
  // True once the open-time filter has run. Distinguishes "every step was filtered out" from
  // "not filtered yet" — both of which leave `visibleSteps` empty.
  const [stepsResolved, setStepsResolved] = useState(false);
  // Tracks real card height; starts with an approximation for the first render's position math.
  const [cardHeight, setCardHeight] = useState(CARD_APPROX_HEIGHT_PX);

  // React DOM refs require null as the initial value (standard React ref convention).
  // eslint-disable-next-line no-null/no-null
  const primaryButtonRef = useRef<HTMLButtonElement>(null);
  // React DOM refs require null as the initial value (standard React ref convention).
  // eslint-disable-next-line no-null/no-null
  const cardRef = useRef<HTMLDivElement>(null);

  // Non-DOM ref: stores prior active element for focus restoration on close.
  const savedFocusRef = useRef<Element | undefined>(undefined);

  // Latest onSkip, so the "nothing left to spotlight" effect below can call it without taking it
  // as a dependency — a caller passing an inline arrow would otherwise re-run that effect (and
  // re-fire onSkip) on every render.
  const onSkipRef = useRef(onSkip);
  useEffect(() => {
    onSkipRef.current = onSkip;
  });

  // Per-instance ids so the SVG mask stays unique and the dialog can describe its body text.
  const maskId = useId();
  const descId = useId();

  useLayoutEffect(() => {
    if (!open) {
      setVisibleSteps([]);
      setStepIndex(0);
      setMeasuredTarget(undefined);
      setStepsResolved(false);
      return;
    }
    // Use measureTarget (not bare querySelector) so presence and measurability agree: a target
    // that exists but has zero area (e.g. an empty wrapper whose conditional child is absent)
    // would otherwise be counted as a step that can never be spotlighted.
    setVisibleSteps(steps.filter((step) => measureTarget(step.target) !== undefined));
    setStepIndex(0);
    setStepsResolved(true);
    // Snapshot steps once on open; intentionally excludes 'steps' from deps so mid-tour
    // locale updates do not reset the user back to step 1.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const currentStep = visibleSteps[stepIndex];
  // `measuredTarget &&` rather than optional chaining: with both sides undefined (nothing measured
  // and no current step) the identity check would otherwise pass and dereference undefined.
  const targetRect =
    measuredTarget && measuredTarget.step === currentStep ? measuredTarget.rect : undefined;
  // The card mounts one commit after the step becomes current (the render guard below returns
  // null until the target has been measured). Effects that reach into the card via refs must
  // re-run when the card appears, not only when the step changes.
  const isCardRendered = targetRect !== undefined;

  // Measure the current target; re-measure on resize, on scroll, and when the target's own box
  // changes.
  useEffect(() => {
    if (!open || !currentStep) return undefined;
    let remeasureFrameId: number | undefined;
    // Reset per step, since the effect re-runs whenever currentStep changes. Separates a target
    // that has never been measurable for this step from one that momentarily cannot be measured.
    let hasMeasuredThisStep = false;
    const measure = () => {
      const r = measureTarget(currentStep.target);
      if (!r) {
        // The target resolved during the open-time filter but has since disappeared (e.g. a
        // conditional toolbar item whose availability probe resolved to false after the tour
        // opened). Drop the step so the tour advances instead of freezing on a blank overlay.
        if (!hasMeasuredThisStep)
          setVisibleSteps((prev) => prev.filter((step) => step !== currentStep));
        // Once measured, keep the last-known-good rect so a momentary layout blip (e.g. a target
        // mid-transition) never blanks the overlay while the step is still viable.
        return;
      }
      hasMeasuredThisStep = true;
      // Returning the previous object when nothing moved skips the re-render entirely —
      // capture-phase scroll ticks fire for scrolls that don't move the target at all.
      setMeasuredTarget((prev) =>
        prev &&
        prev.step === currentStep &&
        prev.rect.top === r.top &&
        prev.rect.left === r.left &&
        prev.rect.width === r.width &&
        prev.rect.height === r.height
          ? prev
          : { step: currentStep, rect: r },
      );
    };
    const scheduleRemeasure = () => {
      if (remeasureFrameId !== undefined) return;
      remeasureFrameId = requestAnimationFrame(() => {
        remeasureFrameId = undefined;
        measure();
      });
    };
    measure();
    window.addEventListener('resize', scheduleRemeasure);
    // Capture-phase passive scroll catches scrolls inside nested containers (panel columns, toolbar).
    window.addEventListener('scroll', scheduleRemeasure, { capture: true, passive: true });
    // A target's box can change with neither a window resize nor a scroll: an rc-dock panel reflows
    // once its web view's content loads, and the toolbar's config area reflows as the sync button
    // and the version tooltip resolve. Both toolbar steps sit in that row, so without this the
    // cutout and card settle on stale geometry — and `measure()`'s last-known-good branch would
    // hide the drift rather than surface it. Observing the root as well catches reflows that move
    // the target without resizing it (font or theme swap, zoom).
    let resizeObserver: ResizeObserver | undefined;
    // ResizeObserver is absent in some test environments; there the resize/scroll listeners stand.
    if (typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(scheduleRemeasure);
      const targetElement = document.querySelector(currentStep.target);
      if (targetElement) resizeObserver.observe(targetElement);
      resizeObserver.observe(document.documentElement);
    }
    return () => {
      window.removeEventListener('resize', scheduleRemeasure);
      window.removeEventListener('scroll', scheduleRemeasure, { capture: true });
      resizeObserver?.disconnect();
      if (remeasureFrameId !== undefined) cancelAnimationFrame(remeasureFrameId);
    };
  }, [open, currentStep]);

  // Dropping the final step leaves stepIndex past the end of the list. Pull it back so the tour
  // lands on the new last step instead of rendering nothing with no way forward.
  useEffect(() => {
    if (visibleSteps.length > 0 && stepIndex >= visibleSteps.length)
      setStepIndex(visibleSteps.length - 1);
  }, [visibleSteps, stepIndex]);

  // Nothing left to spotlight — either no step's target resolved when the tour opened, or every
  // one disappeared while it was open. Report it as a dismissal so the caller can close the tour
  // and record that it ran; otherwise `open` stays true forever behind an overlay that renders
  // nothing and fires no callback.
  useEffect(() => {
    if (open && stepsResolved && visibleSteps.length === 0) onSkipRef.current();
  }, [open, stepsResolved, visibleSteps.length]);

  // Measure real card height after step changes so position math uses the actual size rather than
  // the approximation constant. The functional setter prevents re-render loops.
  // Scoped to step changes and card mount only; card content is stable within a step.
  useLayoutEffect(() => {
    const measured = cardRef.current?.offsetHeight;
    if (measured) setCardHeight((prev) => (prev !== measured ? measured : prev));
  }, [open, stepIndex, isCardRendered]);

  // Save focus on open; restore it on close.
  useEffect(() => {
    if (open) {
      savedFocusRef.current = document.activeElement ?? undefined;
    } else if (
      savedFocusRef.current instanceof HTMLElement ||
      savedFocusRef.current instanceof SVGElement
    ) {
      // Guard against the element being removed from the DOM while the tour was open.
      if (savedFocusRef.current.isConnected) savedFocusRef.current.focus();
      savedFocusRef.current = undefined;
    }
  }, [open]);

  // Move focus to the primary action when the step changes or the card first mounts
  // (accessibility). Without the card-mount dependency, the first open would run this effect
  // while the card is still unmounted and focus would silently stay behind the overlay.
  useEffect(() => {
    if (open && currentStep && isCardRendered) primaryButtonRef.current?.focus();
  }, [open, currentStep, isCardRendered]);

  const isLast = stepIndex === visibleSteps.length - 1;
  const isFirst = stepIndex === 0;

  const handleNext = useCallback(() => {
    if (!isLast) setStepIndex((i) => i + 1);
    else onDone();
  }, [isLast, onDone]);

  const handleBack = useCallback(() => {
    if (!isFirst) setStepIndex((i) => i - 1);
  }, [isFirst]);

  useEffect(() => {
    // Gated on the card actually being on screen, not on `open` alone: the overlay renders nothing
    // until the current step's target has been measured, and an invisible tour must not swallow
    // Escape from a popover or dialog underneath it.
    if (!open || !isCardRendered) return undefined;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        // Capture-phase intercept prevents Escape from reaching popovers or dialogs that might be
        // open behind the overlay — the tour always wins the Escape key while visible.
        e.stopPropagation();
        onSkip();
      }
    };
    window.addEventListener('keydown', onKeyDown, true);
    return () => window.removeEventListener('keydown', onKeyDown, true);
  }, [open, isCardRendered, onSkip]);

  // Focus trap: keep Tab and Shift+Tab inside the card's buttons while the dialog is open. Depends
  // on the card being mounted — on first open the card mounts a commit later than the step, and a
  // trap snapshotted before that would be a permanent no-op for step 1.
  useEffect(() => {
    if (!open || !currentStep || !isCardRendered) return undefined;
    // Query focusable elements once per step — card content is stable within a step.
    const focusable = Array.from(
      cardRef.current?.querySelectorAll<HTMLElement>('button:not([disabled])') ?? [],
    );
    const trapFocus = (e: KeyboardEvent) => {
      if (e.key !== 'Tab' || focusable.length === 0) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const active = document.activeElement;
      // Focus can sit outside the card entirely: clicking the dimmed backdrop blurs the card button
      // and leaves `document.activeElement` on `<body>`, which is neither boundary. Pulling it back
      // here is what keeps Tab from walking into the toolbar and dock behind an `aria-modal`
      // overlay.
      if (!active || !cardRef.current?.contains(active)) {
        e.preventDefault();
        (e.shiftKey ? last : first).focus();
        return;
      }
      if (e.shiftKey) {
        if (active === first) {
          e.preventDefault();
          last.focus();
        }
      } else if (active === last) {
        e.preventDefault();
        first.focus();
      }
    };
    // Capture phase ensures stopPropagation inside card buttons cannot block the trap.
    document.addEventListener('keydown', trapFocus, true);
    return () => document.removeEventListener('keydown', trapFocus, true);
  }, [open, currentStep, isCardRendered]);

  // React component must return null to render nothing.
  // eslint-disable-next-line no-null/no-null
  if (!open || !currentStep || !targetRect) return null;

  const physicalSide = resolvePhysicalSide(currentStep.side ?? 'bottom');
  const cardPos = computeCardPosition(targetRect, physicalSide, cardHeight);

  const spotlightPadding = currentStep.spotlightPadding ?? SPOTLIGHT_PADDING_PX;
  const spotlightX = targetRect.left - spotlightPadding;
  const spotlightY = targetRect.top - spotlightPadding;
  const spotlightWidth = targetRect.width + spotlightPadding * 2;
  const spotlightHeight = targetRect.height + spotlightPadding * 2;

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={currentStep.title}
      aria-describedby={descId}
      // Stable hook for tests: generic modal-dialog selectors also match other overlay dialogs,
      // so anything that needs to find (or avoid) specifically the tour targets this test id.
      data-testid="tour-dialog"
      className="pr-twp tw:fixed tw:inset-0"
      style={{ zIndex: Z_INDEX_ONBOARDING_TOUR }}
    >
      {/* Announces step title + description to screen readers when the step changes. */}
      <p className="tw:sr-only" aria-live="polite" aria-atomic="true">
        {currentStep.title} {currentStep.description}
      </p>

      {/* SVG spotlight mask — dims the page except around the target element.
          The white rect fills the mask; the black cutout creates a transparent hole over the
          target. The SVG has pointerEvents: none so clicks fall through to the dialog below. */}
      <svg
        aria-hidden="true"
        style={{
          position: 'fixed',
          inset: 0,
          width: '100%',
          height: '100%',
          pointerEvents: 'none',
        }}
      >
        <defs>
          <mask id={maskId}>
            <rect width="100%" height="100%" fill="white" />
            <rect
              x={spotlightX}
              y={spotlightY}
              width={spotlightWidth}
              height={spotlightHeight}
              rx="6"
              fill="black"
            />
          </mask>
        </defs>
        {/* The scrim takes the theme's foreground token, so it darkens a light theme and veils a
            dark one rather than being a fixed black wash. */}
        <rect
          width="100%"
          height="100%"
          className="tw:fill-foreground"
          fillOpacity={SCRIM_OPACITY}
          mask={`url(#${maskId})`}
        />
      </svg>

      {/* Step card — positioned adjacent to the spotlight target.
          The overlay div intercepts pointer events over the spotlighted target; navigating via the
          card buttons is the intended interaction while the tour is open. */}
      <div
        ref={cardRef}
        className="tw:fixed tw:flex tw:flex-col tw:gap-2 tw:overflow-y-auto tw:rounded-lg tw:border tw:border-border tw:bg-popover tw:p-4 tw:shadow-lg"
        style={{
          top: cardPos.top,
          left: cardPos.left,
          width: CARD_WIDTH_PX,
          maxHeight: 'calc(100vh - 16px)',
        }}
      >
        <p data-testid="tour-step-counter" className="tw:text-xs tw:text-muted-foreground">
          {formatReplacementString(counterTemplate, {
            count: String(stepIndex + 1),
            total: String(visibleSteps.length),
          })}
        </p>
        <h3 data-testid="tour-step-title" className="tw:text-sm tw:font-semibold">
          {currentStep.title}
        </h3>
        <p id={descId} className="tw:text-sm tw:text-muted-foreground">
          {currentStep.description}
        </p>

        <div className="tw:flex tw:items-center tw:justify-between tw:pt-1">
          <Button variant="ghost" size="sm" onClick={onSkip}>
            {skipLabel}
          </Button>
          <div className="tw:flex tw:gap-2">
            {!isFirst && (
              <Button variant="outline" size="sm" onClick={handleBack}>
                {backLabel}
              </Button>
            )}
            <Button ref={primaryButtonRef} size="sm" onClick={handleNext}>
              {isLast ? doneLabel : nextLabel}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Tour;
